// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetConsultNote The newest version of my note for this appointment
	// (GET /v1/appointments/{appointmentId}/note)
	GetConsultNote(ctx context.Context, request GetConsultNoteRequestObject) (GetConsultNoteResponseObject, error)
	// SaveConsultNote Save the draft note (a signed version is never changed; saving after signing starts a new version)
	// (PUT /v1/appointments/{appointmentId}/note)
	SaveConsultNote(ctx context.Context, request SaveConsultNoteRequestObject) (SaveConsultNoteResponseObject, error)
	// GetAppointmentPrescription The newest version of my prescription for this appointment
	// (GET /v1/appointments/{appointmentId}/prescription)
	GetAppointmentPrescription(ctx context.Context, request GetAppointmentPrescriptionRequestObject) (GetAppointmentPrescriptionResponseObject, error)
	// SaveDraftPrescription Replace the draft prescription. Items are stored exactly as entered; free text only in instructions
	// (PUT /v1/appointments/{appointmentId}/prescription)
	SaveDraftPrescription(ctx context.Context, request SaveDraftPrescriptionRequestObject) (SaveDraftPrescriptionResponseObject, error)
	// CheckDraftPrescription Run the prescribing rules on the draft (draft stage). Per-item result; never a suggestion
	// (POST /v1/appointments/{appointmentId}/prescription/check)
	CheckDraftPrescription(ctx context.Context, request CheckDraftPrescriptionRequestObject) (CheckDraftPrescriptionResponseObject, error)
	// SignPrescription Sign and issue the prescription. Needs a verified doctor, a step-up and the electronic signature
	// (POST /v1/appointments/{appointmentId}/prescription/sign)
	SignPrescription(ctx context.Context, request SignPrescriptionRequestObject) (SignPrescriptionResponseObject, error)
	// GetMyConsultNote The signed note of one of my appointments
	// (GET /v1/me/appointments/{appointmentId}/note)
	GetMyConsultNote(ctx context.Context, request GetMyConsultNoteRequestObject) (GetMyConsultNoteResponseObject, error)
	// ListMyPrescriptions My signed prescriptions, newest first
	// (GET /v1/me/prescriptions)
	ListMyPrescriptions(ctx context.Context, request ListMyPrescriptionsRequestObject) (ListMyPrescriptionsResponseObject, error)
	// GetMyPrescription One of my signed prescriptions (latest version, or the one named by version)
	// (GET /v1/me/prescriptions/{prescriptionId})
	GetMyPrescription(ctx context.Context, request GetMyPrescriptionRequestObject) (GetMyPrescriptionResponseObject, error)
	// ListMyPrescriptionReminders The reminder switch of each item of my latest signed prescription version
	// (GET /v1/me/prescriptions/{prescriptionId}/reminders)
	ListMyPrescriptionReminders(ctx context.Context, request ListMyPrescriptionRemindersRequestObject) (ListMyPrescriptionRemindersResponseObject, error)
	// SetMyPrescriptionReminder Turn one item's reminders off or on again
	// (PUT /v1/me/prescriptions/{prescriptionId}/reminders/{itemRef})
	SetMyPrescriptionReminder(ctx context.Context, request SetMyPrescriptionReminderRequestObject) (SetMyPrescriptionReminderResponseObject, error)
	// GetPatientHistory Signed notes and prescriptions of other doctors, for a patient who shared their history with me
	// (GET /v1/patients/{patientId}/history)
	GetPatientHistory(ctx context.Context, request GetPatientHistoryRequestObject) (GetPatientHistoryResponseObject, error)
	// VerifyPrescription Is this verification reference a genuine, unaltered signed prescription? Shows no patient data
	// (GET /v1/prescription-verifications/{reference})
	VerifyPrescription(ctx context.Context, request VerifyPrescriptionRequestObject) (VerifyPrescriptionResponseObject, error)
	// AmendPrescription Open a new draft version copied from the latest signed one (the old version stays immutable)
	// (POST /v1/prescriptions/{prescriptionId}/amend)
	AmendPrescription(ctx context.Context, request AmendPrescriptionRequestObject) (AmendPrescriptionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

